/* GENERATED by tools/split-map.js from film-engine/src/index.html: the code only moodboard uses. Do not edit; edit the source or the tool. */


    // ── Look board ─────────────────────────────────────────────────────────

    let MOOD_SPECS = {};

    async function loadMoodBoardPage() {
        if (!state.currentProject) return;
        const board = await api(`/projects/${state.currentProject.id}/mood-board`);
        const kinds = ['palette', 'lighting', 'lens', 'framing', 'texture', 'image'];
        document.getElementById('moodKind').innerHTML = kinds.map(k => `<option value="${k}">${k}</option>`).join('');

        // Spec vocabularies come from the server, so the board can never offer
        // a lens or a ratio the engine would refuse.
        const composed = await api(`/projects/${state.currentProject.id}/mood-board/compose`, { method: 'POST', body: JSON.stringify({}) });
        MOOD_SPECS = composed.spec_kinds || {};
        document.getElementById('moodSpecKind').innerHTML = '<option value="">—</option>'
            + Object.entries(MOOD_SPECS).map(([k, v]) => `<option value="${k}">${esc(v.label)}</option>`).join('');
        moodSpecValues();

        document.getElementById('moodEntries').innerHTML = (board.entries || []).map(e => `
            <div class="card">
                <div class="flex-between"><strong>${esc(e.spec_kind || e.kind)}</strong>
                    <button class="btn btn-sm" onclick="moodBoardDelete('${e.id}')">Remove</button></div>
                ${e.image_url ? `<img src="${esc(plateSrc(e.image_url, 480))}" style="width:100%;margin-top:6px;border-radius:4px;"
                        onclick="openPlateViewer('${API_BASE}${esc(e.image_url)}', ${jsAttr(e.note || 'Board reference')})"
                        onerror="this.replaceWith(Object.assign(document.createElement('div'),{className:'text-sm text-muted',textContent:'This reference could not be loaded — the file may have been moved or deleted.'}))">`
                    : (e.image_path ? `<div class="text-sm text-muted" style="margin-top:6px;">This reference has no servable location.</div>` : '')}
                <p class="text-sm" style="margin-top:6px;">${esc(e.spec_value || e.note || '')}</p>
            </div>`).join('') || '<div class="text-muted">Nothing on the board yet.</div>';
        setStatus(`${(board.entries || []).length} board entr(ies)`);
    }

    function moodSpecValues() {
        const kind = document.getElementById('moodSpecKind').value;
        const spec = MOOD_SPECS[kind];
        document.getElementById('moodSpecValue').innerHTML =
            (spec ? spec.allowed : []).map(v => `<option value="${esc(String(v))}">${esc(String(v))}</option>`).join('');
    }

    /** A look reference from outside, pinned to the board and conditioning shots. */
    async function uploadMoodBoardImage(event) {
        if (!state.currentProject) return;
        const note = (document.getElementById('moodNote') || {}).value || '';
        await uploadReferenceImage(event, 'mood-board-image',
            `/projects/${state.currentProject.id}/mood-board/import`,
            note ? { note } : {}, 'loadMoodBoardPage');
    }

    async function moodBoardAdd() {
        const body = { kind: document.getElementById('moodKind').value, note: document.getElementById('moodNote').value };
        const specKind = document.getElementById('moodSpecKind').value;
        if (specKind) { body.spec_kind = specKind; body.spec_value = document.getElementById('moodSpecValue').value; }
        try {
            await api(`/projects/${state.currentProject.id}/mood-board`, { method: 'POST', body: JSON.stringify(body) });
            document.getElementById('moodNote').value = '';
            loadMoodBoardPage();
        } catch (err) { setStatus('Could not add: ' + err.message); }
    }

    async function moodBoardDelete(id) {
        try { await api(`/mood-board/${id}`, { method: 'DELETE' }); loadMoodBoardPage(); }
        catch (err) { setStatus('Could not remove: ' + err.message); }
    }

    async function moodBoardCompose(apply) {
        const res = await api(`/projects/${state.currentProject.id}/mood-board/compose`,
            { method: 'POST', body: JSON.stringify({ apply: !!apply }) });
        const el = document.getElementById('moodComposed');
        el.style.display = '';
        el.innerHTML = `<strong>${apply ? 'Applied' : 'Would apply'}</strong>
            <p class="text-sm" style="margin-top:6px;">${esc(res.style_preset || res.message || '')}</p>
            ${(res.warnings || []).map(w => `<p class="text-sm" style="color:var(--gl-warning,#f59e0b);margin-top:6px;">${esc(w.detail)}</p>`).join('')}
            ${res.effective_style && res.effective_style !== res.style_preset
                ? `<p class="text-sm" style="margin-top:8px;"><strong>What actually reaches a prompt:</strong><br>${esc(res.effective_style)}</p>` : ''}
            ${(res.applied_specs || []).length ? `<p class="text-sm text-muted" style="margin-top:6px;">Settings written: ${res.applied_specs.map(s => esc(s.kind)).join(', ')}</p>` : ''}`;
        setStatus(apply ? 'Look applied' : 'Look previewed — not applied');
    }
